package com.mealmate.payment; import org.springframework.kafka.annotation.*; import org.springframework.kafka.core.*; import org.springframework.stereotype.*; import java.util.*; @Component class PaymentConsumer { final PaymentRepository r; final KafkaTemplate<String,Object> k; PaymentConsumer(PaymentRepository x,KafkaTemplate<String,Object> y){r=x;k=y;} @KafkaListener(topics="food-order-events",groupId="payment-service") void on(Event e){if(r.existsById(e.orderId()))return; r.save(new Payment(e.orderId(),e.failPayment()?"FAILED":"SUCCEEDED")); k.send("payment-events",e.orderId().toString(),new Event(UUID.randomUUID().toString(),e.failPayment()?"PaymentFailed":"PaymentSucceeded",e.orderId(),e.failDeliveryAssignment(),false));} record Event(String eventId,String type,UUID orderId,boolean failPayment,boolean failDeliveryAssignment){} }
